/**
 * HTTP client wrapping `openapi-fetch` with:
 *   - Typed paths from `./schema.d.ts` (regenerated by `npm run api:types`)
 *   - An envelope unwrap that throws `ApiError` on `{ success: false }`
 *   - A middleware stub that injects `Authorization: Bearer <token>` once
 *     Supabase auth is wired (P2-02) and a 401 retry-once-on-refresh.
 *
 * Mock mode bypass: when `env.useMocks` is true the feature's `api.ts`
 * never calls this client; it returns fixtures directly. The client is
 * only imported in real-mode code paths.
 */
import createClient, { type Middleware } from 'openapi-fetch';

import { env } from '@/lib/env';
import type { paths } from './schema';
import type {
  ApiAuthLockout,
  ApiErrorEnvelope,
  ApiErrorPayload,
  ApiEnvelope,
} from './types';

const RATE_LIMIT_TEXT = 'Too many requests';

const baseUrl = env.useMocks ? '' : env.apiUrl.replace(/\/$/, '');

export const api = createClient<paths>({
  baseUrl,
});

let getAccessToken: () => string | null = () => null;
let onUnauthorized: () => void | Promise<void> = () => {};

const authMiddleware: Middleware = {
  async onRequest({ request }) {
    const token = getAccessToken();
    if (token) {
      request.headers.set('Authorization', `Bearer ${token}`);
    }
    return request;
  },
};

const retryMiddleware: Middleware = {
  async onResponse({ request, response }) {
    if (response.status !== 401) return response;
    const token = getAccessToken();
    if (!token) {
      await onUnauthorized();
      return response;
    }
    // A single attempt to refresh the session, then retry the original
    // request once with the new token.
    try {
      await onUnauthorized(); // phase 2 calls supabase.auth.refreshSession() here
    } catch {
      return response;
    }
    const refreshed = getAccessToken();
    if (!refreshed || refreshed === token) return response;
    const retried = new Request(request, {
      headers: new Headers(request.headers),
    });
    (retried.headers as Headers).set('Authorization', `Bearer ${refreshed}`);
    return fetch(retried);
  },
};

api.use(authMiddleware);
api.use(retryMiddleware);

export function configureAuth(opts: {
  getAccessToken: () => string | null;
  onUnauthorized: () => void | Promise<void>;
}) {
  getAccessToken = opts.getAccessToken;
  onUnauthorized = opts.onUnauthorized;
}

/**
 * Unwrap a `{ success, data | error }` envelope response. Throws `ApiError`
 * on any non-2xx, non-JSON, or `{ success: false }` response.
 */
export async function unwrap<T>(response: Response): Promise<T> {
  const status = response.status;
  const contentType = response.headers.get('content-type') ?? '';

  // Rate-limited responses are plain text per API §1.
  if (status === 429) {
    const text = contentType.includes('text/plain')
      ? await response.text()
      : RATE_LIMIT_TEXT;
    throw new ApiErrorImpl('RATE_LIMITED', text || RATE_LIMIT_TEXT, status);
  }

  let payload: unknown = null;
  if (contentType.includes('application/json')) {
    try {
      payload = await response.json();
    } catch {
      throw new ApiErrorImpl('UNKNOWN', 'Invalid JSON in response', status);
    }
  } else {
    const text = await response.text();
    if (status >= 400) {
      throw new ApiErrorImpl('UNKNOWN', text || 'Request failed', status);
    }
    // Empty 2xx with no JSON — callers shouldn't see this in practice.
    return text as unknown as T;
  }

  if (status >= 200 && status < 300 && isOkEnvelope<T>(payload)) {
    return payload.data;
  }

  if (isErrEnvelope(payload)) {
    const code = payload.error.code ?? 'UNKNOWN';
    const message = payload.error.message ?? 'Request failed';
    const lockout = payload as ApiErrorEnvelope & ApiAuthLockout;
    throw new ApiErrorImpl(code, message, status, {
      attemptsRemaining: lockout.attemptsRemaining,
      lockedForSeconds: lockout.lockedForSeconds,
    });
  }

  throw new ApiErrorImpl('UNKNOWN', 'Malformed response', status);
}

function isOkEnvelope<T>(v: unknown): v is ApiEnvelope<T> {
  return (
    typeof v === 'object' &&
    v !== null &&
    (v as { success?: unknown }).success === true &&
    'data' in (v as object)
  );
}

function isErrEnvelope(v: unknown): v is ApiErrorEnvelope & ApiAuthLockout {
  if (typeof v !== 'object' || v === null) return false;
  const o = v as { success?: unknown; error?: ApiErrorPayload };
  return (
    o.success === false &&
    typeof o.error === 'object' &&
    o.error !== null &&
    typeof (o.error as ApiErrorPayload).code === 'string' &&
    typeof (o.error as ApiErrorPayload).message === 'string'
  );
}

export class ApiErrorImpl extends Error {
  readonly code: string;
  readonly status: number;
  readonly attemptsRemaining?: number;
  readonly lockedForSeconds?: number;

  constructor(
    code: string,
    message: string,
    status: number,
    lockout?: ApiAuthLockout,
  ) {
    super(message);
    this.name = 'ApiError';
    this.code = code;
    this.status = status;
    if (lockout?.attemptsRemaining !== undefined) {
      this.attemptsRemaining = lockout.attemptsRemaining;
    }
    if (lockout?.lockedForSeconds !== undefined) {
      this.lockedForSeconds = lockout.lockedForSeconds;
    }
  }
}

// re-export so feature code can `import { ApiError } from '@/api/client'`
export { ApiErrorImpl as ApiError };
